xpath.script:
(function () {
    if (typeof window === 'undefined') return;
    function tag () {
        var vh = window.innerHeight || 800;
        document.querySelectorAll('img:not([loading])').forEach(function (img) {
            var rect = img.getBoundingClientRect();
            // Skip anything in or near the first viewport
            // — that's the LCP candidate, must stay eager.
            if (rect.top < vh + 200) return;
            img.loading  = 'lazy';
            img.decoding = 'async';
        });
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', tag);
    } else {
        tag();
    }
    // Re-tag images that the theme adds after first paint
    // (carousels, infinite-scroll, related products, …).
    if ('MutationObserver' in window) {
        var mo = new MutationObserver(function () { tag(); });
        mo.observe(document.documentElement,
                   { childList: true, subtree: true });
    }
})();
